p=Path('package.json');pkg=json.loads(p.read_text());pkg['scripts'].update({'test:invitation-policy':'node invitation-policy.test.mjs','emulator:test:invitation-rules':'firebase emulators:exec --only firestore --project demo-fidunio-invitation-rules "node firestore-invitation.rules.test.mjs"','test:invitation-install-closeout':'node invitation-install-closeout.test.mjs'});p.write_text(json.dumps(pkg,separators=(',',':'))+'\n')
